contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary inputs
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proofProof, bool[] calldata proofFlags, uint256 ethAmount) public payable {
        // require we can send ethAmount if provided
        if (ethAmount > 0) require(address(this).balance >= ethAmount, "insufficient balance for test");

        // build MerkleMultiProof calldata struct in memory for buy
        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](proofProof.length);
        for (uint256 i = 0; i < proofProof.length; i++) proof.proof[i] = proofProof[i];
        proof.flags = new bool[](proofFlags.length);
        for (uint256 i = 0; i < proofFlags.length; i++) proof.flags[i] = proofFlags[i];

        // observe before
        uint256 beforeVBase = c.virtualBaseTokenReserves();

        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // attempt the buy; catch revert
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, proof) returns (uint256 _net, uint256 _fee, uint256 _proto) {
            reverted = false;
            netInputAmount = _net;
            feeAmount = _fee;
            protocolFeeAmount = _proto;
        } catch {
            reverted = true;
        }

        uint256 afterVBase = c.virtualBaseTokenReserves();

        // General rule:
        // If tokenIds is non-empty then either the call reverted, or virtualBaseTokenReserves increased by at least (netInputAmount - feeAmount - protocolFeeAmount).
        // Note: netInputAmount, feeAmount, protocolFeeAmount are only meaningful when not reverted; in that case the contract's documented behavior is to increase
        // virtualBaseTokenReserves by exactly (netInputAmount - feeAmount - protocolFeeAmount) (it uses that value). We assert at least that increase.
        if (tokenIds.length == 0) {
            // For empty tokenIds we do not assert meaningful invariants about reserves — so just assert we reached the end
            assert(true);
        } else {
            if (reverted) {
                // if reverted, nothing required about reserve change; just assert revert flag true
                assert(reverted == true);
            } else {
                // ensure no underflow in expression: compute expected increment as sum to compare via <=
                uint256 expectedIncrement = netInputAmount + feeAmount + protocolFeeAmount;
                // From contract logic: virtualBaseTokenReserves increased by (netInputAmount - feeAmount - protocolFeeAmount)
                // Rearranged to compare: afterVBase >= beforeVBase + (netInputAmount - feeAmount - protocolFeeAmount)
                // To avoid subtraction underflow in the assert, we compare by adding fee and protocol to before and ensuring after + 2*fee+2*proto >= before + netInput + fee + proto
                // Simpler safe check: compute reportedNetMinusFees = netInputAmount;
                // We'll assert that afterVBase >= beforeVBase + (netInputAmount - feeAmount - protocolFeeAmount) by branching on which side is larger safely.

                // safe check using conditional to avoid underflow: if netInputAmount >= feeAmount + protocolFeeAmount then require afterVBase - beforeVBase >= netInputAmount - feeAmount - protocolFeeAmount
                if (netInputAmount >= feeAmount + protocolFeeAmount) {
                    uint256 inc = afterVBase - beforeVBase;
                    uint256 expected = netInputAmount - feeAmount - protocolFeeAmount;
                    assert(inc >= expected);
                } else {
                    // if netInputAmount < fees, expected decrease would be negative; contract uses SafeCast to add/subtract into uint128 and will still update accordingly
                    // In that case, we conservatively assert that afterVBase >= beforeVBase - (feeAmount + protocolFeeAmount - netInputAmount)
                    uint256 diff = (feeAmount + protocolFeeAmount) - netInputAmount;
                    // ensure beforeVBase >= diff to avoid underflow in subtraction observation — if not, then the contract would have underflowed and reverted which we would have caught earlier
                    if (beforeVBase >= diff) {
                        uint256 minimalAfter = beforeVBase - diff;
                        assert(afterVBase >= minimalAfter);
                    } else {
                        // If before < diff then the contract would likely have reverted; but since we didn't revert, just assert afterVBase is any uint (no-op)
                        assert(true);
                    }
                }
            }
        }
    }

    receive() external payable {}
}

contract InvMutTest {
