    // Single public entry containing all test logic
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proofProof, bool[] calldata proofFlags, uint256 ethAmount) public payable {
        // allow sending ETH from this contract if requested
        if (ethAmount > 0) require(address(this).balance >= ethAmount, "insufficient balance for test");

        // build MerkleMultiProof in memory (top-level, state-changing calls only occur as their own statements)
        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](proofProof.length);
        for (uint256 i = 0; i < proofProof.length; i++) proof.proof[i] = proofProof[i];
        proof.flags = new bool[](proofFlags.length);
        for (uint256 i = 0; i < proofFlags.length; i++) proof.flags[i] = proofFlags[i];

        // observe before-value
        uint256 beforeVBase = c.virtualBaseTokenReserves();

        // perform the buy call as a top-level statement and capture revert via try/catch
        bool didRevert;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        try c.buy{value: ethAmount}(tokenIds, tokenWeights, proof) returns (uint256 _net, uint256 _fee, uint256 _proto) {
            didRevert = false;
            netInputAmount = _net;
            feeAmount = _fee;
            protocolFeeAmount = _proto;
        } catch {
            didRevert = true;
        }

        // observe after-value
        uint256 afterVBase = c.virtualBaseTokenReserves();

        // Single general assert as required:
        // If tokenIds is non-empty then either the call reverted, or the observed increase in virtualBaseTokenReserves is at least (netInputAmount - feeAmount - protocolFeeAmount).
        // For empty tokenIds we do not assert any relation (the statement still must be reached), so we express it as a tautology dependent on tokenIds.length==0.
        assert(
            tokenIds.length == 0 ||
            didRevert ||
            (
                // when netInputAmount >= fee+proto, compare increase safely
                (netInputAmount >= feeAmount + protocolFeeAmount && (afterVBase >= beforeVBase && afterVBase - beforeVBase >= netInputAmount - feeAmount - protocolFeeAmount))
                ||
                // when netInputAmount < fee+proto, expected increment is negative; require that afterVBase did not decrease by more than (fee+proto - net)
                (netInputAmount < feeAmount + protocolFeeAmount && (beforeVBase >= (feeAmount + protocolFeeAmount - netInputAmount) ? afterVBase >= beforeVBase - (feeAmount + protocolFeeAmount - netInputAmount) : true))
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
