    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proofProof, bool[] calldata proofFlags, uint256 ethAmount) public payable {
        // We only consider non-empty buys with ETH being sent. Require some reasonable bounds so checker can reason.
        require(tokenIds.length > 0, "need tokenIds");
        require(tokenIds.length == tokenWeights.length, "len mismatch");
        require(proofProof.length <= 8 && proofFlags.length <= 8, "proofs bounded");
        // This contract must hold the ETH to send
        if (ethAmount > 0) require(address(this).balance >= ethAmount, "insufficient balance for test");

        // build MerkleMultiProof in memory
        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](proofProof.length);
        for (uint256 i = 0; i < proofProof.length; i++) proof.proof[i] = proofProof[i];
        proof.flags = new bool[](proofFlags.length);
        for (uint256 i = 0; i < proofFlags.length; i++) proof.flags[i] = proofFlags[i];

        // observe factory address and c balance before call
        address factory = address(c.factory());
        uint256 beforeFactoryBal = factory.balance;

        bool didRevert;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // perform the buy call as a top-level statement and capture revert via try/catch
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, proof) returns (uint256 _net, uint256 _fee, uint256 _proto) {
            didRevert = false;
            netInputAmount = _net;
            feeAmount = _fee;
            protocolFeeAmount = _proto;
        } catch {
            didRevert = true;
        }

        uint256 afterFactoryBal = factory.balance;

        // General rule: for non-empty tokenIds and when the buy call did NOT revert and baseToken==address(0), the factory's ETH balance must have increased by at least protocolFeeAmount reported by the call.
        // We require baseToken==address(0) via observable c.baseToken() before asserting.
        assert(
            // if reverted, no obligation
            didRevert ||
            // else if base token is non-zero, we don't assert (only care about ETH case)
            (c.baseToken() != address(0)) ||
            // otherwise, buy succeeded and baseToken==0: factory balance increased by at least protocolFeeAmount
            (afterFactoryBal >= beforeFactoryBal && afterFactoryBal - beforeFactoryBal >= protocolFeeAmount)
        );
    }

    receive() external payable {}
}

