contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry
    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount) public payable {
        // require some basic bounds
        require(tokenIds.length > 0, "need tokenIds");
        // limit array length to keep verification tractable
        require(tokenIds.length <= 8, "too many tokens");

        // read NFT address and pool nft balance before
        address nftAddr = c.nft();
        uint256 beforeBalance = ERC721(nftAddr).balanceOf(address(c));

        // If pool uses native ETH as base token, we must send ETH equal to baseTokenAmount
        bool poolUsesEth = (c.baseToken() == address(0));
        if (poolUsesEth) {
            // ensure test contract has enough balance to forward
            require(address(this).balance >= baseTokenAmount, "insufficient balance for ETH transfer");
        }

        bool didRevert;
        // perform the deposit; send ETH only when required by poolUsesEth
        if (poolUsesEth) {
            try c.deposit{value: baseTokenAmount}(tokenIds, baseTokenAmount) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        } else {
            try c.deposit(tokenIds, baseTokenAmount) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        }

        uint256 afterBalance = ERC721(nftAddr).balanceOf(address(c));

        // General rule: either deposit reverted, or the NFT balance increased exactly by tokenIds.length
        assert(didRevert || afterBalance == beforeBalance + tokenIds.length);
    }

    // receive to accept ETH if needed by calls
    receive() external payable {}
}

