        // Build MerkleMultiProof in calldata-compatible memory layout
        C.MerkleMultiProof memory mp;
        mp.proof = proof;
        mp.flags = flags;

        // Perform buy and capture whether it reverted
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, mp) returns (uint256 _net, uint256 _fee, uint256 _prot) {
            reverted = false;
            netInputAmount = _net;
            feeAmount = _fee;
            protocolFeeAmount = _prot;
        } catch {
            reverted = true;
        }

        // Read price after (only valid if not reverted)
        uint256 priceAfter = c.price();

        // General rule: if buy succeeded, the pool must have increased its virtualBaseTokenReserves relative to virtualNftReserves
        // enough that the price (which is proportional to virtualBaseTokenReserves/virtualNftReserves) is strictly greater than before.
