        C.MerkleMultiProof memory mp;
        mp.proof = proofData;
        mp.flags = flags;

        // perform the buy as a top-level state-changing call; capture revert and returned values
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, mp) returns (uint256 _net, uint256 _fee, uint256 _prot) {
            reverted = false;
            netInputAmount = _net;
